formal_property.sva:
// Check that data_rand[0] equals lfsr[31:0] when RandWidth == 32, and that no zero-extension or truncation occurs when RandWidth == 32
// This property can detect whether the assumption of correct width holds; if RandWidth != 32, random quality may be compromised
property p_data_rand_width_match;
  @(posedge clk_i) disable iff (!rst_ni)
  (RandWidth == 32) |-> (data_rand[0] == lfsr[31:0]);
endproperty
assert property(p_data_rand_width_match);

